    "aStarter": "import hashlib, hmac\n\ndef seal_aead(key: bytes, nonce: bytes, pt: bytes, aad: bytes) -> tuple[bytes, bytes]:\n    # TODO\n    pass\n\ndef open_aead(key: bytes, nonce: bytes, ct: bytes, aad: bytes, tag: bytes):\n    # TODO\n    pass",
    "aHint": "import hashlib, hmac\n\ndef _keystream(key: bytes, nonce: bytes, length: int) -> bytes:\n    out = bytearray()\n    ctr = 0\n    while len(out) < length:\n        blk = hashlib.sha256(key + nonce + ctr.to_bytes(4, \"big\")).digest()\n        out.extend(blk)\n        ctr += 1\n    return bytes(out[:length])\n\ndef _mac(key: bytes, nonce: bytes, ct: bytes, aad: bytes) -> bytes:\n    msg = nonce + len(aad).to_bytes(4, \"big\") + aad + ct\n    return hmac.new(key, msg, hashlib.sha256).digest()\n\ndef seal_aead(key: bytes, nonce: bytes, pt: bytes, aad: bytes) -> tuple[bytes, bytes]:\n    ks = _keystream(key, nonce, len(pt))\n    ct = bytes(a ^ b for a, b in zip(pt, ks))\n    tag = _mac(key, nonce, ct, aad)\n    return ct, tag\n\ndef open_aead(key: bytes, nonce: bytes, ct: bytes, aad: bytes, tag: bytes):\n    exp = _mac(key, nonce, ct, aad)\n    if not hmac.compare_digest(exp, tag):\n        return None\n    ks = _keystream(key, nonce, len(ct))\n    return bytes(a ^ b for a, b in zip(ct, ks))",
