    "eStarter": "import base64, hashlib, hmac, json, re\n\ndef verify_hs256_jwt(token: str, key_ring: dict[str, bytes], expected_iss: str, expected_aud: str, now_ts: int):\n    # TODO\n    pass",
    "eHint": "import base64, hashlib, hmac, json, re\n\ndef _b64d(s: str) -> bytes:\n    return base64.urlsafe_b64decode(s + \"=\" * (-len(s) % 4))\n\ndef verify_hs256_jwt(token: str, key_ring: dict[str, bytes], expected_iss: str, expected_aud: str, now_ts: int):\n    parts = token.split(\".\")\n    if len(parts) != 3:\n        return False, \"malformed\"\n    h_b, p_b, sig_b = parts\n    try:\n        hdr = json.loads(_b64d(h_b))\n        pay = json.loads(_b64d(p_b))\n        sig = _b64d(sig_b)\n    except Exception:\n        return False, \"decode_error\"\n    if hdr.get(\"alg\") != \"HS256\":\n        return False, \"bad_alg\"\n    kid = hdr.get(\"kid\", \"\")\n    if not re.fullmatch(r\"[A-Za-z0-9_-]{1,32}\", str(kid)) or kid not in key_ring:\n        return False, \"bad_kid\"\n    exp_sig = hmac.new(key_ring[kid], f\"{h_b}.{p_b}\".encode(\"ascii\"), hashlib.sha256).digest()\n    if not hmac.compare_digest(exp_sig, sig):\n        return False, \"bad_sig\"\n    if pay.get(\"exp\", 0) <= now_ts:\n        return False, \"expired\"\n    if pay.get(\"iss\") != expected_iss or pay.get(\"aud\") != expected_aud:\n        return False, \"claims_mismatch\"\n    return True, pay",
    "eTest": "import base64, hashlib, hmac, json\ndef _enc(d): return base64.urlsafe_b64encode(json.dumps(d).encode()).rstrip(b\"=\").decode()\ndef make_tok(h, p, k):\n    hp = f\"{_enc(h)}.{_enc(p)}\"\n    sig = base64.urlsafe_b64encode(hmac.new(k, hp.encode(), hashlib.sha256).digest()).rstrip(b\"=\").decode()\n    return f\"{hp}.{sig}\"\nkeys = {\"k1\": b\"secret_key\"}\nt_ok = make_tok({\"alg\": \"HS256\", \"kid\": \"k1\"}, {\"iss\": \"auth\", \"aud\": \"api\", \"exp\": 200, \"sub\": \"u1\"}, b\"secret_key\")\nassert verify_hs256_jwt(t_ok, keys, \"auth\", \"api\", 100)[0] is True\nt_none = f\"{_enc({'alg': 'none', 'kid': 'k1'})}.{_enc({'iss': 'auth', 'aud': 'api', 'exp': 200})}.\"\nassert verify_hs256_jwt(t_none, keys, \"auth\", \"api\", 100) == (False, \"bad_alg\")\nt_kid = make_tok({\"alg\": \"HS256\", \"kid\": \"../k1\"}, {\"iss\": \"auth\", \"aud\": \"api\", \"exp\": 200}, b\"secret_key\")\nassert verify_hs256_jwt(t_kid, keys, \"auth\", \"api\", 100) == (False, \"bad_kid\")\nprint('All checks passed.')",
