    "eStarter": "from collections import deque\n\nclass ZanzibarCheck:\n    def __init__(self, tuples: list[tuple[str, str, str]], hierarchy: dict[str, str]):\n        # TODO\n        pass\n\n    def check(self, obj: str, rel: str, user: str) -> bool:\n        # TODO\n        pass",
    "eHint": "from collections import deque, defaultdict\n\nclass ZanzibarCheck:\n    def __init__(self, tuples: list[tuple[str, str, str]], hierarchy: dict[str, str]):\n        self.edges = defaultdict(list)\n        for o, r, s in tuples:\n            self.edges[(o, r)].append(s)\n        self.reverse_hier = defaultdict(list)\n        for hi, lo in hierarchy.items():\n            self.reverse_hier[lo].append(hi)\n\n    def check(self, obj: str, rel: str, user: str) -> bool:\n        q = deque([(obj, rel)])\n        vis = {(obj, rel)}\n        while q:\n            co, cr = q.popleft()\n            for hi in self.reverse_hier.get(cr, []):\n                if (co, hi) not in vis:\n                    vis.add((co, hi))\n                    q.append((co, hi))\n            for subj in self.edges.get((co, cr), []):\n                if subj == user:\n                    return True\n                if \"#\" in subj:\n                    go, gr = subj.split(\"#\", 1)\n                    if (go, gr) not in vis:\n                        vis.add((go, gr))\n                        q.append((go, gr))\n        return False",
    "eTest": "z = ZanzibarCheck([(\"doc:1\", \"owner\", \"user:bob\"), (\"doc:1\", \"viewer\", \"group:eng#member\"), (\"group:eng\", \"member\", \"user:alice\")], {\"owner\": \"editor\", \"editor\": \"viewer\"})\nassert z.check(\"doc:1\", \"viewer\", \"user:bob\") is True\nassert z.check(\"doc:1\", \"viewer\", \"user:alice\") is True\nassert z.check(\"doc:1\", \"editor\", \"user:alice\") is False\nprint('All checks passed.')",
