    "aStarter": "def evaluate_abac(req: dict, policies: list[dict]) -> tuple[bool, str]:\n    # TODO\n    pass",
    "aHint": "def evaluate_abac(req: dict, policies: list[dict]) -> tuple[bool, str]:\n    def matches(cond):\n        for k, exp in cond.items():\n            val = req.get(k)\n            if isinstance(exp, list):\n                if val not in exp:\n                    return False\n            elif val != exp:\n                return False\n        return True\n    denies = sorted(p[\"id\"] for p in policies if p[\"effect\"] == \"DENY\" and matches(p[\"match\"]))\n    if denies:\n        return False, denies[0]\n    allows = sorted(p[\"id\"] for p in policies if p[\"effect\"] == \"ALLOW\" and matches(p[\"match\"]))\n    if allows:\n        return True, allows[0]\n    return False, \"DEFAULT_DENY\"",
